public interface ModelProvider extends AutoCloseable {
    Flow.Publisher<ModelStreamEvent> stream(ModelRequest request);

    default CompletionStage<ModelResponse> complete(ModelRequest request) {
        var result = new java.util.concurrent.CompletableFuture<ModelResponse>();
        var responseId = new java.util.concurrent.atomic.AtomicReference<String>();
        var content = new java.util.ArrayList<Content>();
        var text = new StringBuilder();
        stream(request).subscribe(new Flow.Subscriber<>() {
            @Override
            public void onSubscribe(Flow.Subscription subscription) {
                subscription.request(Long.MAX_VALUE);
            }

            @Override
            public void onNext(ModelStreamEvent event) {
                if (event instanceof ModelStreamEvent.Started started) responseId.set(started.responseId());
                else if (event instanceof ModelStreamEvent.TextDelta delta) text.append(delta.text());
                else if (event instanceof ModelStreamEvent.ToolCallReady ready) content.add(ready.toolCall());
                else if (event instanceof ModelStreamEvent.Completed completed) {
                    if (!text.isEmpty()) content.add(0, new Content.Text(text.toString()));
                    String id = responseId.get();
                    if (id == null || id.isBlank()) {
                        result.completeExceptionally(new ProviderException(new ProviderFailure(
                                "provider.invalid_response", java.util.Map.of("provider", request.model().provider()),
                                java.util.Optional.empty())));
                    } else {
                        result.complete(new ModelResponse(id, content, completed.usage(), completed.stopReason()));
                    }
                } else if (event instanceof ModelStreamEvent.Failed failed) {
                    result.completeExceptionally(new ProviderException(failed.failure()));
                }
            }

            @Override
            public void onError(Throwable throwable) {
                result.completeExceptionally(throwable);
            }

            @Override
            public void onComplete() {
                if (!result.isDone()) {
                    result.completeExceptionally(new ProviderException(new ProviderFailure(
                            "provider.invalid_response", java.util.Map.of("provider", request.model().provider()),
                            java.util.Optional.empty())));
                }
            }
        });
        return result;
    }

    default CompletionStage<Void> closeAsync() {
        return java.util.concurrent.CompletableFuture.completedFuture(null);
    }
